#!/usr/bin/env node
import { parseArgs } from 'node:util'
import { listMaskIds } from './library.js'
import { personaHome } from './paths.js'

/**
 * Target coding agents the CLI can install/activate/remove against. The MVP
 * registry contains only Claude Code, with `claude` accepted as an alias.
 */
const AGENT_ALIASES: Record<string, string> = {
  claude: 'claude-code',
  'claude-code': 'claude-code',
}

function resolveAgent(agent: string | undefined): string {
  if (agent === undefined) return '<choose at command time>'
  return AGENT_ALIASES[agent] ?? agent
}

function runList(): number {
  const ids = listMaskIds(personaHome())
  if (ids.length === 0) {
    process.stderr.write('No persona masks found in ~/.persona/\n')
    return 0
  }
  process.stdout.write(ids.join('\n') + '\n')
  return 0
}

/**
 * The multi-agent command shape is fixed from the start. `install`, `activate`,
 * and `remove` all accept `--agent <agent>` so later slices can fill in the
 * behavior without changing the CLI surface.
 */
function runReserved(command: string, rest: string[]): number {
  const { values } = parseArgs({
    args: rest,
    options: { agent: { type: 'string' } },
    allowPositionals: true,
    strict: true,
  })
  const target = resolveAgent(values.agent)
  process.stderr.write(`persona ${command}: not yet implemented (target agent: ${target})\n`)
  return 1
}

const RESERVED_COMMANDS = new Set(['install', 'activate', 'remove'])

function main(argv: string[]): number {
  const [command, ...rest] = argv

  if (command === 'list') return runList()
  if (command !== undefined && RESERVED_COMMANDS.has(command)) return runReserved(command, rest)

  process.stderr.write(`persona: unknown command: ${command ?? '(none)'}\n`)
  return 2
}

process.exit(main(process.argv.slice(2)))

import { homedir } from 'node:os'
import { join } from 'node:path'

/** The persona mask library directory, `~/.persona/`. */
export function personaHome(): string {
  return join(homedir(), '.persona')
}

import { spawnSync } from 'node:child_process'
import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { realpathSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const REPO_ROOT = resolve(here, '..')
const CLI_ENTRY = resolve(REPO_ROOT, 'src', 'cli.ts')
const TMP_ROOT = realpathSync(tmpdir())

/** Captured result of one `persona` invocation. */
export interface RunResult {
  stdout: string
  stderr: string
  code: number
}

export interface RunOptions {
  /** Working directory for the spawned process. Defaults to the repo root. */
  cwd?: string
}

/**
 * Integration test harness for the `persona` CLI.
 *
 * Every harness gets its own throwaway HOME so the real `~/.persona` and
 * `~/.claude` are never read or written. It drives the real CLI as a child
 * process and captures stdout, stderr, and the exit code, and exposes helpers
 * to seed persona masks and assert filesystem side effects.
 */
export interface Harness {
  /** The temp HOME this harness operates under. */
  readonly home: string
  /** `<home>/.persona` — the persona mask library directory. */
  readonly personaDir: string
  /** `<home>/.claude` — Claude Code's user-level config directory. */
  readonly claudeDir: string
  /** Run `persona <args...>` under this harness's HOME. */
  run(args: string[], opts?: RunOptions): RunResult
  /**
   * Seed a persona mask at `~/.persona/<id>/`. By default writes a minimal
   * `persona.md` so the directory is discoverable as a mask. Pass `files` to
   * control the contents; omit `persona.md` from `files` to seed a directory
   * that is deliberately *not* a mask.
   */
  seedMask(id: string, files?: Record<string, string>): void
  /** Write a file relative to HOME, creating parent directories. */
  writeFile(relToHome: string, content: string): void
  /** Read a file relative to HOME. */
  readFile(relToHome: string): string
  /** Whether a path relative to HOME exists. */
  exists(relToHome: string): boolean
  /** Remove the temp HOME. */
  cleanup(): void
}

const DEFAULT_PERSONA_MD = `---
id: PLACEHOLDER
name: Placeholder Mask
description: A seeded persona mask for tests.
self_address: 测试者
user_address: 用户
---

## Linguistic Style
seeded
`

export function createHarness(): Harness {
  const home = mkdtempSync(join(TMP_ROOT, 'persona-test-'))
  const personaDir = join(home, '.persona')
  const claudeDir = join(home, '.claude')

  const abs = (relToHome: string): string => join(home, relToHome)

  return {
    home,
    personaDir,
    claudeDir,

    run(args, opts = {}): RunResult {
      const result = spawnSync(process.execPath, ['--import', 'tsx', CLI_ENTRY, ...args], {
        cwd: opts.cwd ?? REPO_ROOT,
        encoding: 'utf8',
        env: {
          ...process.env,
          HOME: home,
          USERPROFILE: home,
        },
      })
      if (result.error) throw result.error
      return {
        stdout: result.stdout ?? '',
        stderr: result.stderr ?? '',
        code: result.status ?? -1,
      }
    },

    seedMask(id, files): void {
      const maskDir = join(personaDir, id)
      mkdirSync(maskDir, { recursive: true })
      const contents = files ?? { 'persona.md': DEFAULT_PERSONA_MD.replace('PLACEHOLDER', id) }
      for (const [name, content] of Object.entries(contents)) {
        const target = join(maskDir, name)
        mkdirSync(dirname(target), { recursive: true })
        writeFileSync(target, content)
      }
    },

    writeFile(relToHome, content): void {
      const target = abs(relToHome)
      mkdirSync(dirname(target), { recursive: true })
      writeFileSync(target, content)
    },

    readFile(relToHome): string {
      return readFileSync(abs(relToHome), 'utf8')
    },

    exists(relToHome): boolean {
      return existsSync(abs(relToHome))
    },

    cleanup(): void {
      // Defense in depth: never rm anything outside the temp root.
      const realHome = realpathSync(home)
      if (!realHome.startsWith(TMP_ROOT) || !realHome.includes('persona-test-')) {
        throw new Error(`refusing to clean up suspicious harness HOME: ${realHome}`)
      }
      rmSync(home, { recursive: true, force: true })
    },
  }
}

import { afterEach, beforeEach, describe, expect, it } from 'vitest'
import { createHarness, type Harness } from './harness.js'

describe('reserved multi-agent commands', () => {
  let h: Harness

  beforeEach(() => {
    h = createHarness()
  })

  afterEach(() => {
    h.cleanup()
  })

  it.each(['install', 'activate', 'remove'])(
    'recognizes `%s` with a --agent option but reports it is not yet implemented',
    (command) => {
      const { stderr, code } = h.run([command, 'senpai-rust', '--agent', 'claude-code'])

      // Recognized command (not an "unknown command" error) ...
      expect(stderr).not.toMatch(/unknown command/i)
      // ... but the behavior is reserved for a later slice.
      expect(code).not.toBe(0)
      expect(stderr).toMatch(/not yet implemented/i)
    },
  )

  it('accepts `claude` as an alias for the claude-code agent target', () => {
    const { stderr } = h.run(['install', 'senpai-rust', '--agent', 'claude'])

    expect(stderr).toContain('claude-code')
  })
})

import { afterEach, beforeEach, describe, expect, it } from 'vitest'
import { createHarness, type Harness } from './harness.js'

describe('persona list', () => {
  let h: Harness

  beforeEach(() => {
    h = createHarness()
  })

  afterEach(() => {
    h.cleanup()
  })

  it('lists a persona mask in the library', () => {
    h.seedMask('senpai-rust')

    const { stdout, code } = h.run(['list'])

    expect(code).toBe(0)
    expect(stdout.trim().split('\n')).toContain('senpai-rust')
  })

  it('presents imported and manually placed masks identically, and only lists dirs with persona.md', () => {
    // An imported mask: it has a lock-file entry recording its source.
    h.seedMask('senpai-rust')
    h.writeFile(
      '.persona/.lock.json',
      JSON.stringify({ version: 1, personas: { 'senpai-rust': { sourceType: 'github' } } }),
    )
    // A manually placed mask: no lock entry, but still a first-class local mask.
    h.seedMask('kouhai-go')
    // A directory that is NOT a mask: it has no persona.md.
    h.writeFile('.persona/scratch/notes.md', 'just notes')

    const { stdout, stderr, code } = h.run(['list'])

    expect(code).toBe(0)
    // Both masks appear, sorted, with no managed/unmanaged grouping or markers.
    expect(stdout.trim().split('\n')).toEqual(['kouhai-go', 'senpai-rust'])
    // The non-mask directory and the lock file are not listed.
    expect(stdout).not.toContain('scratch')
    expect(stdout).not.toContain('.lock.json')
    // No source/managed vocabulary leaks into the default output.
    expect(stdout.toLowerCase()).not.toMatch(/managed|unmanaged|imported|source/)
    expect(stderr).toBe('')
  })

  it('exits cleanly with an empty stdout and a hint when the library is empty', () => {
    // No masks seeded: ~/.persona/ does not even exist yet.
    const { stdout, stderr, code } = h.run(['list'])

    expect(code).toBe(0)
    expect(stdout.trim()).toBe('')
    expect(stderr).toMatch(/no persona masks/i)
  })
})

import { tmpdir } from 'node:os'
import { realpathSync } from 'node:fs'
import { afterEach, beforeEach, describe, expect, it } from 'vitest'
import { createHarness, type Harness } from './harness.js'

describe('integration test harness', () => {
  let h: Harness

  beforeEach(() => {
    h = createHarness()
  })

  afterEach(() => {
    h.cleanup()
  })

  it('captures stdout, stderr, and the exit code', () => {
    const { stdout, stderr, code } = h.run(['definitely-not-a-command'])

    expect(code).toBe(2)
    expect(stderr).toMatch(/unknown command/i)
    expect(stdout).toBe('')
  })

  it('runs commands under a temp HOME so the real ~/.persona is never touched', () => {
    expect(realpathSync(h.home).startsWith(realpathSync(tmpdir()))).toBe(true)
    expect(h.personaDir).toBe(`${h.home}/.persona`)

    // The CLI only ever sees masks seeded into this temp HOME — proof that HOME
    // is redirected and the developer's real library is invisible.
    h.seedMask('only-mask')
    const { stdout } = h.run(['list'])
    expect(stdout.trim().split('\n')).toEqual(['only-mask'])
  })

  it('can seed masks and assert filesystem side effects relative to HOME', () => {
    h.seedMask('senpai-rust', { 'persona.md': '# stub', 'memory.md': 'mask memory' })

    expect(h.exists('.persona/senpai-rust/persona.md')).toBe(true)
    expect(h.readFile('.persona/senpai-rust/memory.md')).toBe('mask memory')
    expect(h.exists('.persona/senpai-rust/eval.md')).toBe(false)
  })
})

